1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
24	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
31	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
32	    @Mapping(target = "bulkSignupWarning", ignore = true)
33	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Derives an owner's age band from the birth date, computed against the registration date
38	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
39	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
40	     * {@code null} when no birth date is present, so the field is omitted from the response.
41	     */
42	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
43	        if (owner == null || owner.getBirthDate() == null) {
44	            return null;
45	        }
46	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
47	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
48	        if (age < 18) {
49	            return OwnerDto.AgeBandEnum.MINOR;
50	        }
51	        if (age < 65) {
52	            return OwnerDto.AgeBandEnum.ADULT;
53	        }
54	        return OwnerDto.AgeBandEnum.SENIOR;
55	    }
56	
57	    /**
58	     * Derives an owner's duplicate-detection identity key as
59	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
60	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
61	     * telephone, email or household id contributes the empty string in its position.
62	     */
63	    default String formatIdentityKey(Owner owner) {
64	        if (owner == null) {
65	            return null;
66	        }
67	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
68	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
69	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
70	        return telephone + "|" + email + "|" + householdId;
71	    }
72	
73	    /**
74	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
75	     * (non-null and non-blank), otherwise {@code PHONE}.
76	     */
77	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
78	        if (owner == null) {
79	            return null;
80	        }
81	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
82	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
83	    }
84	
85	    /**
86	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
87	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
88	     * When the customer code is absent it falls back to resolving the region directly, preferring the
89	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
90	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
91	     * {@code "UNKNOWN"} when neither resolves.
92	     */
93	    default String formatLocality(Owner owner) {
94	        if (owner == null) {
95	            return null;
96	        }
97	        String code = owner.getCustomerCode();
98	        if (code != null) {
99	            int dash = code.indexOf('-');
100	            if (dash > 0) {
101	                return code.substring(0, dash);
102	            }
103	        }
104	        String fromPostcode = regionForPostcode(owner.getPostcode());
105	        if (fromPostcode != null) {
106	            return fromPostcode;
107	        }
108	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
109	            case "Sydney" -> "NSW";
110	            case "Melbourne" -> "VIC";
111	            case "Brisbane" -> "QLD";
112	            default -> "UNKNOWN";
113	        };
114	    }
115	
116	    /**
117	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
118	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
119	     * no known range, signalling that the caller should fall back to the city-to-region table.
120	     */
121	    private String regionForPostcode(String postcode) {
122	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
123	            return null;
124	        }
125	        int value = Integer.parseInt(postcode);
126	        if (value >= 2000 && value <= 2099) {
127	            return "NSW";
128	        }
129	        if (value >= 3000 && value <= 3099) {
130	            return "VIC";
131	        }
132	        if (value >= 4000 && value <= 4099) {
133	            return "QLD";
134	        }
135	        return null;
136	    }
137	
138	    /**
139	     * Computes an owner's membership level, a number from 1 to 3: starting at 1, plus 1 when an email
140	     * is present, plus 1 when the owner's namesake count is 0, capped at 3 (level 4 is reserved for
141	     * tenure).
142	     */
143	    default Integer formatMembershipLevel(Owner owner) {
144	        if (owner == null) {
145	            return null;
146	        }
147	        int level = 1;
148	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
149	        if (hasEmail) {
150	            level++;
151	        }
152	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
153	        if (unique) {
154	            level++;
155	        }
156	        return Math.min(level, 3);
157	    }
158	
159	    /**
160	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
161	     * customer code. Returns {@code null} when the customer code is absent.
162	     */
163	    default Integer formatCheckDigit(Owner owner) {
164	        if (owner == null || owner.getCustomerCode() == null) {
165	            return null;
166	        }
167	        String code = owner.getCustomerCode();
168	        int sum = 0;
169	        boolean dbl = true;
170	        for (int i = code.length() - 1; i >= 0; i--) {
171	            char c = code.charAt(i);
172	            if (c < '0' || c > '9') {
173	                continue;
174	            }
175	            int d = c - '0';
176	            if (dbl) {
177	                d *= 2;
178	                if (d > 9) {
179	                    d -= 9;
180	                }
181	            }
182	            sum += d;
183	            dbl = !dbl;
184	        }
185	        return (10 - (sum % 10)) % 10;
186	    }
187	
188	    /**
189	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
190	     * digits of the registration-date year (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the
191	     * customer code or registration date is absent.
192	     */
193	    default String formatMembershipNumber(Owner owner) {
194	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
195	            return null;
196	        }
197	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
198	    }
199	
200	    /**
201	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
202	     */
203	    default String formatDisplayName(Owner owner) {
204	        if (owner == null) {
205	            return null;
206	        }
207	        return owner.getLastName() + ", " + owner.getFirstName();
208	    }
209	
210	    /**
211	     * Formats an owner's initials as the upper-cased first letters of the first and last
212	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
213	     */
214	    default String formatInitials(Owner owner) {
215	        if (owner == null) {
216	            return null;
217	        }
218	        return initial(owner.getFirstName()) + initial(owner.getLastName());
219	    }
220	
221	    private String initial(String name) {
222	        if (name == null || name.isEmpty()) {
223	            return "";
224	        }
225	        return Character.toUpperCase(name.charAt(0)) + ".";
226	    }
227	
228	    Owner toOwner(OwnerDto ownerDto);
229	
230	    @Mapping(target = "id", ignore = true)
231	    @Mapping(target = "pets", ignore = true)
232	    Owner toOwner(OwnerFieldsDto ownerDto);
233	
234	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
235	
236	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
237	
238	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
239	        OwnerPageDto ownerPageDto = new OwnerPageDto();
240	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
241	        ownerPageDto.setPage(ownerPage.getNumber());
242	        ownerPageDto.setSize(ownerPage.getSize());
243	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
244	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
245	        return ownerPageDto;
246	    }
247	}
